const a=window.ARTIST_CONFIG;document.querySelectorAll('[data-name]').forEach(x=>x.textContent=a.name);document.title=a.name+' / Artist';document.documentElement.style.setProperty('--accent',/^#[0-9a-f]{6}$/i.test(a.accent)?a.accent:'#65edff');document.getElementById('sound').textContent=a.sound;document.getElementById('bio').textContent=a.bio;function links(target,items){for(const item of items){const el=document.createElement('a');try{const u=new URL(item.url);if(!['https:','http:'].includes(u.protocol))continue;el.href=u.href}catch{continue}el.textContent=item.title;el.className='card';el.target='_blank';el.rel='noopener';target.append(el)}}links(document.getElementById('mixes'),a.mixes);links(document.getElementById('socials'),a.socials);for(const show of a.shows){const p=document.createElement('p');p.className='card';p.textContent=show.date+' / '+show.venue;document.getElementById('dates').append(p)}const booking=document.getElementById('bookingLink');booking.textContent=a.booking;booking.href='mailto:'+encodeURIComponent(a.booking);